import time
import numpy as np
import jax
import jax.numpy as jnp
import tensorcircuit as tc
from tensorcircuit.channels import _sqrt

tc.set_backend("jax")
tc.set_dtype("complex64")
backend = tc.backend
n_qubits = 12
theta = 0.31

g00 = tc.gates.Gate(np.array([[1.0, 0.0], [0.0, 0.0]], dtype=np.complex64))
g01 = tc.gates.Gate(np.array([[0.0, 1.0], [0.0, 0.0]], dtype=np.complex64))
g10 = tc.gates.Gate(np.array([[0.0, 0.0], [1.0, 0.0]], dtype=np.complex64))
g11 = tc.gates.Gate(np.array([[0.0, 0.0], [0.0, 1.0]], dtype=np.complex64))

def bitflip_kraus(p01, p10):
    return [
        _sqrt(1.0 - p01) * g00 + _sqrt(1.0 - p10) * g11,
        _sqrt(p10) * g01,
        _sqrt(p01) * g10,
    ]

def prepare_state(circuit, kind):
    if kind == 0:
        circuit.h(0)
        for i in range(n_qubits - 1):
            circuit.cnot(i, i + 1)
    elif kind == 1:
        for i in range(0, n_qubits - 1, 2):
            circuit.x(i + 1)
            circuit.h(i)
            circuit.cnot(i, i + 1)
    elif kind == 3:
        for i in range(n_qubits):
            circuit.h(i)

def apply_with_mode(circuit, p01, p10, mode):
    kraus = bitflip_kraus(p01, p10)
    for left in range(0, n_qubits - 1, 2):
        circuit.rxx(left, left + 1, theta=theta)
        circuit.general_kraus(kraus, left)
        circuit.general_kraus(kraus, left + 1)
        if mode == "each":
            circuit._contract()
    if mode == "layer":
        circuit._contract()
    for left in range(1, n_qubits - 1, 2):
        circuit.rxx(left, left + 1, theta=theta)
        circuit.general_kraus(kraus, left)
        circuit.general_kraus(kraus, left + 1)
        if mode == "each":
            circuit._contract()
    if mode == "layer":
        circuit._contract()

def one(p01, p10, kind, mode, how):
    circuit = tc.DMCircuit(n_qubits)
    prepare_state(circuit, kind)
    if mode in ("layer", "each"):
        circuit._contract()
    apply_with_mode(circuit, p01, p10, mode)
    if how == "expect":
        z_vals = [backend.real(circuit.expectation_ps(z=[i])) for i in range(n_qubits)]
        parity = backend.real(circuit.expectation_ps(z=list(range(n_qubits))))
        return backend.sum(backend.stack(z_vals + [parity]))
    dm = circuit.densitymatrix()
    z0 = backend.real(circuit.expectation_ps(z=[0]))
    return backend.real(backend.trace(dm)) + z0

p01 = jnp.float32(0.034)
p10 = jnp.float32(0.011)

for mode in ["none", "layer", "each"]:
    for how in ["expect", "dm"]:
        fn = jax.jit(lambda a,b, mode=mode, how=how: one(a,b,0,mode,how))
        t0 = time.time()
        val = fn(p01, p10)
        val.block_until_ready()
        t1 = time.time()
        val2 = fn(p01, p10)
        val2.block_until_ready()
        t2 = time.time()
        print(f"{mode:5s} {how:6s} compile+run {t1-t0:7.3f} run {t2-t1:7.3f} val {np.array(val2)}")
